import { PageHeaderModule } from 'src/app/view/components/app/page-header/page-header.module';
import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';

import { SettingRoutingModule } from './setting-routing.module';
import { AdminLoginCodeComponent } from './admin-login-code.component';
import { SettingComponent } from './setting.component';
import { HttpClientModule, HTTP_INTERCEPTORS } from '@angular/common/http';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { IonicModule } from '@ionic/angular';
import { SliderService } from '../../../../../data/service/site/Slider.service';
import { AccountInterceptor } from 'src/app/core/utility/account.interceptor';
import { LoadingModule } from '../../../../components/common/loading/loading.module';
import { CourseService } from '../../../../../data/service/course/course.service';
import { OrderService } from '../../../../../data/service/order/order.service';
import { UserService } from '../../../../../data/service/user/user.service';


@NgModule({
  declarations: [SettingComponent, AdminLoginCodeComponent],
  imports: [
    PageHeaderModule,
    CommonModule,
    SettingRoutingModule,
    IonicModule,
    HttpClientModule,
    FormsModule,
    ReactiveFormsModule,
    LoadingModule
  ],
  providers: [
    SliderService,
    OrderService,
    UserService,
    CourseService,
    {
      provide: HTTP_INTERCEPTORS,
      useClass: AccountInterceptor,
      multi: true
    }
  ]
})
export class SettingModule { }
