import { HttpClient } from '@angular/common/http';
import { Component, OnDestroy } from '@angular/core';
import { NavController } from '@ionic/angular';
import { Subscription } from 'rxjs';
import { timeout } from 'rxjs/operators';

interface PendingLoginCode { status: 'waiting' | 'ready'; accountEmail?: string; accounts?: string[]; code?: string; expiresAt?: string; remainingSeconds?: number; }

@Component({
  selector: 'app-admin-login-code',
  templateUrl: './admin-login-code.component.html',
  styles: [':host { direction: rtl; } ion-card { max-width: 620px; margin: 24px auto; } .code { font-size: 2.6rem; letter-spacing: .35em; text-align: center; user-select: text; }']
})
export class AdminLoginCodeComponent implements OnDestroy {
  code = '';
  seconds = 0;
  busy = false;
  accountEmail = '';
  selectedEmail = '';
  accounts: string[] = [];
  message = 'حساب مقصد را انتخاب کنید؛ می‌توانید برای خودتان یا ادمین دیگر کد ورود بسازید.';
  private request?: Subscription;
  private timer?: ReturnType<typeof setInterval>;
  private pollTimer?: ReturnType<typeof setInterval>;
  private active = false;
  private watching = false;
  private expiresAt = 0;
  private readonly visibilityChanged = () => {
    if (document.hidden) { this.suspend(); }
    else if (this.active && this.watching) { this.refresh(); }
  };

  constructor(private http: HttpClient, private navController: NavController) {
    document.addEventListener('visibilitychange', this.visibilityChanged);
  }

  backToSettings(): void {
    void this.navController.navigateRoot('/SuperAdminPanel/Setting', { replaceUrl: true });
  }

  accountChanged(event: Event): void {
    const email = (event as CustomEvent<{ value: string }>).detail?.value;
    if (typeof email === 'string') { this.selectAccount(email); }
  }

  selectAccount(email: string): void {
    if (!this.accounts.includes(email) || email === this.selectedEmail) { return; }
    this.clear();
    this.selectedEmail = email;
    this.message = 'در حال بررسی کد حساب انتخاب‌شده…';
    this.refresh();
  }

  refresh(): void {
    if (!this.active || document.hidden) { return; }
    this.startWatching();
    this.fetchCode();
  }

  private startWatching(): void {
    this.watching = true;
    if (!this.pollTimer) { this.pollTimer = setInterval(() => this.fetchCode(), 5000); }
  }

  generate(): void {
    if (!this.active || document.hidden || this.busy) { return; }
    this.startWatching();
    this.busy = true;
    this.hideCode();
    this.request = this.http.post<PendingLoginCode>('/api/Account/AdminLoginRecoveryCode', null, {
      params: this.selectedEmail ? { accountEmail: this.selectedEmail } : {},
      headers: { 'ngsw-bypass': 'true', 'Cache-Control': 'no-cache' }
    }).pipe(timeout(15000)).subscribe({
      next: result => this.showPending(result), error: error => this.showError(error)
    });
  }

  private fetchCode(): void {
    if (this.busy || !this.active || !this.watching || document.hidden) { return; }
    this.busy = true;
    this.request = this.http.get<PendingLoginCode>('/api/Account/AdminLoginRecoveryCode', {
      params: { _: Date.now().toString(), ...(this.selectedEmail ? { accountEmail: this.selectedEmail } : {}) },
      headers: { 'ngsw-bypass': 'true', 'Cache-Control': 'no-cache' }
    }).pipe(timeout(15000)).subscribe({
      next: result => this.showPending(result), error: error => this.showError(error)
    });
  }

  private showPending(result: PendingLoginCode): void {
    this.busy = false;
    this.hideCode();
    if (this.selectedEmail && result.accountEmail?.toLowerCase() !== this.selectedEmail.toLowerCase()) {
      this.clear();
      this.message = 'پاسخ سرور با حساب انتخاب‌شده مطابقت ندارد؛ نسخهٔ جدید بک‌اند را نصب کنید.';
      return;
    }
    this.accountEmail = result.accountEmail || '';
    this.selectedEmail = this.accountEmail;
    this.accounts = result.accounts || (this.accountEmail ? [this.accountEmail] : []);
    this.expiresAt = typeof result.remainingSeconds === 'number'
      ? Date.now() + Math.min(300, Math.max(0, result.remainingSeconds)) * 1000
      : Math.min(Date.now() + 300000, Date.parse(result.expiresAt || ''));
    if (result.status === 'ready' && /^\d{6}$/.test(result.code || '') && this.expiresAt > Date.now()) {
      this.code = result.code;
      this.message = 'این کد را برای ورود حساب انتخاب‌شده استفاده کنید. ایجاد یا ارسال کد جدید برای این حساب، قبلی را باطل می‌کند.';
      this.tick();
      this.timer = setInterval(() => this.tick(), 1000);
    } else {
      this.message = 'کد ورود فعالی وجود ندارد؛ از دکمهٔ ایجاد کد بدون ارسال استفاده کنید یا در دستگاه دیگر درخواست پیامک/ایمیل بدهید.';
    }
  }

  private showError(error: { status: number }): void {
    this.busy = false;
    this.hideCode();
    if (error.status === 401 || error.status === 403 || error.status === 404) { this.clear(); }
    this.message = error.status === 401 || error.status === 403
      ? 'دسترسی به این بخش نیازمند نشست فعال یکی از دو ادمین مجاز و فعال بودن حساب مقصد است.'
      : error.status === 404 ? 'نسخهٔ بک‌اند از این بخش پشتیبانی نمی‌کند؛ بستهٔ جدید بک‌اند را نصب و سرویس را راه‌اندازی مجدد کنید.'
      : 'دریافت پاسخ انجام نشد؛ دوباره بررسی می‌شود.';
  }

  private tick(): void {
    this.seconds = Math.max(0, Math.ceil((this.expiresAt - Date.now()) / 1000));
    if (!this.seconds) { this.hideCode(); this.message = 'اعتبار کد پایان یافت؛ در دستگاه دیگر کد جدید درخواست کنید.'; }
  }

  private hideCode(): void {
    if (this.timer) { clearInterval(this.timer); this.timer = undefined; }
    this.code = '';
    this.seconds = 0;
    this.expiresAt = 0;
  }

  private suspend(): void {
    this.request?.unsubscribe();
    this.request = undefined;
    if (this.pollTimer) { clearInterval(this.pollTimer); this.pollTimer = undefined; }
    this.hideCode();
    this.busy = false;
  }

  clear(): void { this.watching = false; this.suspend(); this.accountEmail = ''; }
  ionViewWillEnter(): void { this.active = true; this.selectedEmail = ''; this.accounts = []; this.refresh(); }
  ionViewWillLeave(): void { this.active = false; this.clear(); }
  ngOnDestroy(): void { this.clear(); document.removeEventListener('visibilitychange', this.visibilityChanged); }
}
